export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,
  generatedAt = new Date().toISOString()
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && typeof thresholds === 'object') {
    const thresholdEntries = Object.entries(thresholds).map(([metric, min]) => ({
      metric,
      min
    }));
    const thresholdResults = evaluateThresholds(thresholdEntries, evaluations);
    report.thresholds = thresholdResults;
    report.passed = thresholdResults.every((t) => t.passed);
  } else {
    report.thresholds = [];
  }

  return report;
}

