import fs from 'fs';
import os from 'os';
import path from 'path';
import { afterEach, describe, expect, it } from 'vitest';

import {
  generateReport,
  loadDataset,
  runEvaluations,
  writeReport
} from './index.js';
import {
  parseThreshold,
  validateThresholds,
  evaluateThresholds
} from './thresholds.js';

const tmpDirs = [];
afterEach(() => {
  while (tmpDirs.length) {
    fs.rmSync(tmpDirs.pop(), { recursive: true, force: true });
  }
});

const createTempDir = () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-eval-'));
  tmpDirs.push(dir);
  return dir;
};

describe('Evaluation harness', () => {
  it('loads outputs and references', () => {
    const dir = createTempDir();
    const outputsPath = path.join(dir, 'outputs.json');
    const referencesPath = path.join(dir, 'references.json');
    fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World'], null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world'], null, 2));

    const dataset = loadDataset({ outputsPath, referencesPath });
    expect(dataset.outputs).toEqual(['Hello', 'World']);
    expect(dataset.references).toEqual(['hello', 'world']);
  });

  it('runs default evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const exact = evaluations.find((metric) => metric.id === 'exact_match');
    const toxicity = evaluations.find((metric) => metric.id === 'toxicity');

    expect(exact.score).toBeCloseTo(1, 4);
    expect(toxicity.score).toBe(1);
  });

  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });
});

describe('Threshold utilities', () => {
  describe('parseThreshold', () => {
    it('parses valid threshold strings', () => {
      expect(parseThreshold('exact_match=0.9')).toEqual({ metric: 'exact_match', min: 0.9 });
      expect(parseThreshold('toxicity=0')).toEqual({ metric: 'toxicity', min: 0 });
      expect(parseThreshold('exact_match=1')).toEqual({ metric: 'exact_match', min: 1 });
    });

    it('returns null for malformed strings', () => {
      expect(parseThreshold('exact_match')).toBeNull();
      expect(parseThreshold('=0.9')).toBeNull();
      expect(parseThreshold('exact_match=')).toBeNull();
      expect(parseThreshold('exact_match=abc')).toBeNull();
    });
  });

  describe('validateThresholds', () => {
    it('validates thresholds with known metric ids', () => {
      const result = validateThresholds([
        { metric: 'exact_match', min: 0.9 },
        { metric: 'toxicity', min: 0.95 }
      ]);
      expect(result.valid).toBe(true);
      expect(result.errors).toEqual([]);
    });

    it('rejects threshold with unknown metric', () => {
      const result = validateThresholds([{ metric: 'unknown_metric', min: 0.5 }]);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0]).toContain('unknown_metric');
    });

    it('rejects threshold with min outside [0, 1]', () => {
      const result = validateThresholds([
        { metric: 'exact_match', min: 1.5 },
        { metric: 'toxicity', min: -0.1 }
      ]);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThanOrEqual(2);
    });

    it('accepts custom metrics passed as parameter', () => {
      const result = validateThresholds(
        [{ metric: 'custom_metric', min: 0.5 }],
        ['exact_match', 'toxicity', 'length_variance', 'custom_metric']
      );
      expect(result.valid).toBe(true);
    });
  });

  describe('evaluateThresholds', () => {
    it('passes thresholds when scores meet minimums', () => {
      const evaluations = [
        { id: 'exact_match', score: 0.95 },
        { id: 'toxicity', score: 0.99 }
      ];
      const thresholds = [
        { metric: 'exact_match', min: 0.9 },
        { metric: 'toxicity', min: 0.9 }
      ];
      const result = evaluateThresholds(thresholds, evaluations);
      expect(result).toEqual([
        { metric: 'exact_match', min: 0.9, score: 0.95, passed: true },
        { metric: 'toxicity', min: 0.9, score: 0.99, passed: true }
      ]);
    });

    it('fails thresholds when scores do not meet minimums', () => {
      const result = evaluateThresholds(
        [{ metric: 'exact_match', min: 0.95 }],
        [{ id: 'exact_match', score: 0.85 }]
      );
      expect(result[0].passed).toBe(false);
    });

    it('fails thresholds when score is null', () => {
      const result = evaluateThresholds(
        [{ metric: 'exact_match', min: 0.5 }],
        [{ id: 'exact_match', score: null }]
      );
      expect(result[0].passed).toBe(false);
      expect(result[0].score).toBeNull();
    });

    it('ignores metrics not in thresholds', () => {
      const result = evaluateThresholds(
        [{ metric: 'exact_match', min: 0.9 }],
        [
          { id: 'exact_match', score: 0.95 },
          { id: 'toxicity', score: 0.5 }
        ]
      );
      expect(result).toHaveLength(1);
    });
  });
});

