/**
 * Generate an evaluation report.
 * @param {Object} config
 * @param {Array} config.evaluations - Metric evaluation results
 * @param {string} config.outputsPath - Path to outputs file
 * @param {string} [config.referencesPath] - Path to references file
 * @param {Object} [config.thresholds] - Thresholds to check: { metricId: minScore }
 * @param {string} [config.generatedAt] - ISO timestamp of report generation
 * @returns {Object} Report with { metadata, metrics, thresholds?, passed? }
 */
export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  thresholds,
